# Auto-generated by mobility_customizations "Export Customizations to App".
# Do not edit: this file is overwritten on every export.
#
# Applies the customizations exported to this app without needing the
# mobility_customizations app to be installed:
#
# * customizations/install/*.json   -> applied once per site (on install, or on the
#                                      next migrate for sites that already have the app)
# * customizations/updates/<name>/  -> applied by the generated patches on migrate;
#                                      on a fresh install patches are skipped, so they
#                                      are applied here instead
#
# Registered in hooks.py as after_install / after_migrate.

import json
import os

import frappe
from frappe.modules.utils import sync_customizations_for_doctype

APP = __name__.split(".")[0]
CUSTOMIZATIONS_FOLDER = "customizations"
INSTALL_FOLDER = "install"
UPDATES_FOLDER = "updates"
# shared with mobility_customizations, so a file is never applied twice
APPLIED_INSTALL_KEY = "mobility_applied_install_customizations"


def after_install():
	apply_install_customizations()
	apply_update_customizations()


def after_migrate():
	try:
		doctypes = apply_install_customizations()
		if doctypes:
			# keep the (newer) update customizations on top of the install baseline
			apply_update_customizations(doctypes)
	except Exception:
		# never block migration
		frappe.log_error(title=f"Install customizations failed for {APP}")


def apply_install_customizations() -> list[str]:
	folder = frappe.get_app_path(APP, CUSTOMIZATIONS_FOLDER, INSTALL_FOLDER)
	if not os.path.isdir(folder):
		return []

	value = frappe.db.get_global(APPLIED_INSTALL_KEY)
	applied = json.loads(value) if value else []
	applied_doctypes = []

	for fname in sorted(os.listdir(folder)):
		if not fname.endswith(".json"):
			continue
		key = f"{APP}/{fname}"
		if key in applied:
			continue

		with open(os.path.join(folder, fname)) as f:
			data = json.load(f)

		if not frappe.db.exists("DocType", data.get("doctype")):
			# doctype's app not installed yet; retry on a later migrate
			continue

		sync_customizations_for_doctype(data, folder, fname)
		applied.append(key)
		applied_doctypes.append(data["doctype"])

	if applied_doctypes:
		frappe.db.set_global(APPLIED_INSTALL_KEY, json.dumps(applied))
		frappe.clear_cache()

	return applied_doctypes


def apply_update_customizations(doctypes: list[str] | None = None):
	root = frappe.get_app_path(APP, CUSTOMIZATIONS_FOLDER, UPDATES_FOLDER)
	if not os.path.isdir(root):
		return

	# oldest first (folder name ends with YYYYMMDD_HHMMSS)
	names = sorted(
		(n for n in os.listdir(root) if os.path.isdir(os.path.join(root, n))), key=lambda n: (n[-15:], n)
	)
	for name in names:
		folder = os.path.join(root, name)
		for fname in sorted(os.listdir(folder)):
			if not fname.endswith(".json"):
				continue
			with open(os.path.join(folder, fname)) as f:
				data = json.load(f)
			if doctypes is not None and data.get("doctype") not in doctypes:
				continue
			if not frappe.db.exists("DocType", data.get("doctype")):
				continue
			sync_customizations_for_doctype(data, folder, fname)

	frappe.clear_cache()
